def _get_available_ports():
    """ Tries to find the available usb2serial port on your system. """
    if platform.system() == 'Darwin':
        return glob.glob('/dev/tty.usb*')

    elif platform.system() == 'Linux':
        return glob.glob('/dev/ttyACM*') + glob.glob('/dev/ttyUSB*')

    elif platform.system() == 'Windows':
        import _winreg
        import itertools

        ports = []
        path = 'HARDWARE\\DEVICEMAP\\SERIALCOMM'
        key = _winreg.OpenKey(_winreg.HKEY_LOCAL_MACHINE, path)

        for i in itertools.count():
            try:
                ports.append(str(_winreg.EnumValue(key, i)[1]))
            except WindowsError:
                return ports

    return []


def get_available_ports(only_free=False):
    ports = _get_available_ports()

    if only_free:
        ports = list(set(ports) - set(DxlIO.get_used_ports()))

    return ports


def find_port(ids, strict=True):
    """ Find the port with the specified attached motor ids.

        :param list ids: list of motor ids to find
        :param bool strict: specify if all ids should be find (when set to False, only half motor must be found)

        .. warning:: If two (or more) ports are attached to the same list of motor ids the first match will be returned.

    """
    for port in get_available_ports():
        for DxlIOCls in (DxlIO, Dxl320IO):
            try:
                with DxlIOCls(port) as dxl:
                    founds = len(dxl.scan(ids))

                    if strict and founds == len(ids):
                        return port

                    if not strict and founds >= len(ids) / 2:
                        return port
            except DxlError:
                continue

    raise IndexError('No suitable port found for ids {}!'.format(ids))


def autodetect_robot():
    """ Creates a :class:`~pypot.robot.robot.Robot` by detecting dynamixel motors on all available ports. """
    motor_controllers = []

    for port in get_available_ports():
        for DxlIOCls in (DxlIO, Dxl320IO):
            dxl_io = DxlIOCls(port)
            ids = dxl_io.scan()

            if not ids:
                dxl_io.close()
                continue

            models = dxl_io.get_model(ids)

            motorcls = {
                'MX': DxlMXMotor,
                'RX': DxlAXRXMotor,
                'AX': DxlAXRXMotor,
                'XL': DxlXL320Motor
            }

            motors = [motorcls[model[:2]](id, model=model)
                      for id, model in zip(ids, models)]

            c = BaseDxlController(dxl_io, motors)
            motor_controllers.append(c)

    return Robot(motor_controllers)

from ..workspace import Block
from twisted.internet import defer
from .variables import lexical_variable

import operator


class logic_null (Block):
	def eval (self):
		return defer.succeed(None)


class logic_boolean (Block):
	def eval (self):
		return defer.succeed(self.fields['BOOL'] == 'TRUE')


class logic_negate (Block):
	outputType = bool

	def eval (self):
		def negate (result):
			if result is None:
				return None

			return result == False

		self._complete = self.getInputValue('BOOL').addCallback(negate)
		return self._complete


_operators_map = {
	"EQ": operator.eq,
	"NEQ": operator.ne,
	"LT": operator.lt,
	"LTE": operator.le,
	"GT": operator.gt,
	"GTE": operator.ge
}

def _compare (lhs, rhs, op_id):
	if lhs is None or rhs is None:
		return None

	op = _operators_map[op_id]
	return op(lhs, rhs)

	# Emit a warning if bad op given

class logic_compare (Block):
	outputType = bool

	def eval (self):
		lhs = self.getInputValue('A')
		rhs = self.getInputValue('B')
		op_id = self.fields['OP']

		def _eval (results):
			lhs, rhs = results
			return _compare(lhs, rhs, op_id)

		self._complete = defer.gatherResults([lhs, rhs]).addCallback(_eval)
		return self._complete


class lexical_variable_compare (lexical_variable):
	outputType = bool

	def eval (self):
		variable = self._getVariable()

		if variable is None:
			self.emitLogMessage(
				"Unknown variable: " + str(self.getFieldValue('VAR')),
				"error"
			)

			return defer.succeed(None)

		value = self.getFieldValue('VALUE')
		op_id = self.getFieldValue('OP')

		unit = self.getFieldValue('UNIT', None)

		if isinstance(unit, (int, float)):
			value *= unit

		return defer.succeed(_compare(variable.value, value, op_id))


class logic_operation (Block):
	outputType = bool

	def eval (self):
		@defer.inlineCallbacks
		def _run ():
			op = self.fields['OP']
			lhs = yield self.getInputValue('A')

			if lhs is None:
				return

			if op == "AND":
				if bool(lhs):
					rhs = yield self.getInputValue('B')

					if rhs is None:
						return

					defer.returnValue(bool(rhs))
				else:
					defer.returnValue(False)
			elif op == "OR":
				if bool(lhs):
					defer.returnValue(True)
				else:
					rhs = yield self.getInputValue('B')

					if rhs is None:
						return

					defer.returnValue(bool(rhs))

			# Emit a warning
			return

		self._complete = _run()
		return self._complete


class logic_ternary (Block):
	# TODO: outputType of then and else should be the same.
	# this is then the outputType of the logic_ternary block.

	def eval (self):
		@defer.inlineCallbacks
		def _run ():
			test = yield self.getInputValue('IF')

			if test is None:
				return

			if bool(test):
				result = yield self.getInputValue('THEN')
				defer.returnValue(result)
			else:
				result = yield self.getInputValue('ELSE')
				defer.returnValue(result)

		self._complete = _run()
		return self._complete

