import os

import jsonschema
import yaml

from snapcraft.internal import common


class SnapcraftSchemaError(Exception):

    @property
    def message(self):
        return self._message

    def __init__(self, message):
        self._message = message


class Validator:

    def __init__(self, snapcraft_yaml=None):
        """Create a validation instance for snapcraft_yaml."""
        self._snapcraft = snapcraft_yaml if snapcraft_yaml else {}
        self._load_schema()

    @property
    def schema(self):
        """Return all schema properties."""

        return self._schema['properties'].copy()

    @property
    def part_schema(self):
        """Return part-specific schema properties."""

        sub = self.schema['parts']['patternProperties']
        properties = sub['^(?!plugins$)[a-z0-9][a-z0-9+-\/]*$']['properties']
        return properties

    def _load_schema(self):
        schema_file = os.path.abspath(os.path.join(
            common.get_schemadir(), 'snapcraft.yaml'))
        try:
            with open(schema_file) as fp:
                self._schema = yaml.load(fp)
        except FileNotFoundError:
            raise SnapcraftSchemaError(
                'snapcraft validation file is missing from installation path')

    def validate(self):
        format_check = jsonschema.FormatChecker()
        try:
            jsonschema.validate(
                self._snapcraft, self._schema, format_checker=format_check)
        except jsonschema.ValidationError as e:
            messages = [e.message]
            path = []
            while e.absolute_path:
                element = e.absolute_path.popleft()
                # assume numbers are indices and use 'xxx[123]' notation.
                if isinstance(element, int):
                    path[-1] = '{}[{}]'.format(path[-1], element)
                else:
                    path.append(str(element))
            if path:
                messages.insert(0, "The '{}' property does not match the "
                                   "required schema:".format('/'.join(path)))
            if e.cause:
                messages.append('({})'.format(e.cause))

            raise SnapcraftSchemaError(' '.join(messages))

import sys
from pdb import Pdb
from ipdb.__main__ import update_stdout, def_colors, wrap_sys_excepthook

class Tdb(Pdb):
    def __init__(self, *args, **kwargs):
        Pdb.__init__(self, *args, **kwargs)
        self.botframe = None
        self.quitting = False
        self.stopframe = None
        self.codemap = {}
        self.entered = False

    def add_trace(self, func):
        code = func.__code__
        self.codemap[code] = 0

    def trace_dispatch(self, frame, event, arg):
        if self.quitting:
            return # None
        if event == 'line':
            return self.dispatch_line(frame)
        if event == 'call':
            return self.dispatch_call(frame, arg)
        if event == 'return':
            return self.dispatch_return(frame, arg)
        if event == 'exception':
            return self.dispatch_exception(frame, arg)
        if event == 'c_call':
            return self.trace_dispatch
        if event == 'c_exception':
            return self.trace_dispatch
        if event == 'c_return':
            return self.trace_dispatch
        print(('bdb.Bdb.dispatch: unknown debugging event:', repr(event)))
        return self.trace_dispatch


    def dispatch_call(self, frame, arg):
        if not self.entered:
            f_code = frame.f_code
            if f_code in self.codemap:
                self.entered = True
                self.codemap[f_code] += 1
                self._set_stopinfo(frame, None)
                return self.trace_dispatch
            else:
                return None

        # XXX 'arg' is no longer used
        if self.botframe is None:
            # First call of dispatch since reset()
            self.botframe = frame.f_back # (CT) Note that this may also be None!
            return self.trace_dispatch
        if not (self.stop_here(frame) or self.break_anywhere(frame)):
            # No need to trace this function
            return # None
        self.user_call(frame, arg)
        if self.quitting: raise BdbQuit
        return self.trace_dispatch

    def set_trace(self, frame=None):
        """
        """
        update_stdout()
        wrap_sys_excepthook()
        if frame is None:
            frame = sys._getframe().f_back
        #pdb = Tdb(def_colors)
        self.reset()
        self.set_step()
        sys.settrace(self.trace_dispatch)

def with_trace(f):
    @wraps(f)
    def tracing(*args, **kwargs):
        set_trace()
        return f(*args, **kwargs)
    return tracing

class Trace(object):
    def __init__(self, *args):
        self.tdb = Tdb(def_colors)

        funcs = list(filter(callable, args))
        for func in funcs:
            self.add_function(func)

    def add_function(self, func):
        self.tdb.add_trace(func)

    def __enter__(self):
        self.tdb.set_trace()
        return self

    def __exit__(self, type, value, traceback):
        sys.settrace(None)

