from typing import Optional, List, Iterator, Iterable, TYPE_CHECKING

from cirq.interop.quirk.cells.cell import Cell, CELL_SIZES, CellMaker

if TYPE_CHECKING:
    import cirq


class InputCell(Cell):
    """A modifier that provides a quantum input to gates in the same column."""

    def __init__(self, qubits: Iterable['cirq.Qid'], letter: str):
        self.qubits = tuple(qubits)
        self.letter = letter

    def gate_count(self) -> int:
        return 0

    def with_line_qubits_mapped_to(self, qubits: List['cirq.Qid']) -> 'Cell':
        return InputCell(qubits=Cell._replace_qubits(self.qubits, qubits), letter=self.letter)

    def modify_column(self, column: List[Optional['Cell']]):
        for i in range(len(column)):
            cell = column[i]
            if cell is not None:
                column[i] = cell.with_input(self.letter, self.qubits)


class SetDefaultInputCell(Cell):
    """A persistent modifier that provides a fallback classical input."""

    def __init__(self, letter: str, value: int):
        self.letter = letter
        self.value = value

    def gate_count(self) -> int:
        return 0

    def with_line_qubits_mapped_to(self, qubits: List['cirq.Qid']) -> 'Cell':
        return self

    def persistent_modifiers(self):
        return {f'set_default_{self.letter}': lambda cell: cell.with_input(self.letter, self.value)}


def generate_all_input_cell_makers() -> Iterator[CellMaker]:
    # Quantum inputs.
    yield from _input_family("inputA", "a")
    yield from _input_family("inputB", "b")
    yield from _input_family("inputR", "r")
    yield from _input_family("revinputA", "a", rev=True)
    yield from _input_family("revinputB", "b", rev=True)

    # Classical inputs.
    yield CellMaker("setA", 2, lambda args: SetDefaultInputCell('a', args.value))
    yield CellMaker("setB", 2, lambda args: SetDefaultInputCell('b', args.value))
    yield CellMaker("setR", 2, lambda args: SetDefaultInputCell('r', args.value))


def _input_family(identifier_prefix: str, letter: str, rev: bool = False) -> Iterator[CellMaker]:
    for n in CELL_SIZES:
        yield CellMaker(
            identifier=identifier_prefix + str(n),
            size=n,
            maker=lambda args: InputCell(
                qubits=args.qubits[::-1] if rev else args.qubits, letter=letter
            ),
        )

import datetime
import uuid

from flask import current_app as app
from flask import url_for

from database import db
from sqlalchemy import Column, DateTime, String, Text
from sqlalchemy.dialects.postgresql import UUID


class Poster(db.Model):
    __tablename__ = 'posters'

    id = Column(UUID(as_uuid=True), primary_key=True)
    title = Column(String(400), nullable=False, default='Untitled')
    authors = Column(Text)
    abstract = Column(Text)
    source_url = Column(String(400), nullable=False)
    download_url = Column(String(400), nullable=False)
    presented_at = Column(String(200))
    created_at = Column('create_date', DateTime, default=datetime.datetime.now())
    id_admin = Column(UUID(as_uuid=True), unique=True, nullable=False)
    email = Column(String(50))

    def __init__(self, title, source_url, download_url, authors=None,
                 abstract=None, presented_at=None):
        self.id = uuid.uuid4()
        self.title = title
        self.authors = authors
        self.abstract = abstract
        self.source_url = source_url
        self.download_url = download_url
        self.presented_at = presented_at
        self.id_admin = uuid.uuid4()

    def __repr__(self):
        return '<User {}>'.format(str(self.id))

    def serialize(self):
        return {
            'id': self.id,
            'title': self.title,
            'authors': self.authors,
            'abstract': self.abstract,
            'source_url': self.source_url,
            'download_url': self.download_url,
            'presented_at': self.presented_at,
            'created_at': self.created_at.isoformat(),
            'thumbnail_url': self.thumbnail_url(),
        }

    def public_url(self, absolute=False):
        return url_for('get_poster', id=self.id, _external=absolute)

    def admin_url(self, absolute=False):
        return url_for('edit_poster', id_admin=self.id_admin, _external=absolute)

    def qrcode_svg_url(self, absolute=False):
        return url_for('get_qrcode_svg', id=self.id, _external=absolute)

    def qrcode_png_url(self, absolute=False):
        return url_for('get_qrcode_png', id=self.id, _external=absolute)

    def is_image(self):
        return self.download_url.endswith('.png') or self.download_url.endswith('.jpg')

    def viewable_download_url(self):
        cloudinary = app.config['CLOUDINARY_BASE_URL']
        if self.is_image() or self.download_url.startswith(cloudinary):
            return self.download_url
        return '{}/image/fetch/{}'.format(cloudinary, self.download_url)

    def thumbnail_url(self):
        cloudinary = app.config['CLOUDINARY_BASE_URL']
        transformations = 'c_thumb,w_370,h_200,f_png'
        if self.download_url.startswith(cloudinary):
            return self.download_url.replace('/upload/', '/upload/{}/'.format(transformations))
        return '{}/image/fetch/{}/{}'.format(cloudinary, transformations, self.download_url)
